// run with: bare lib/node_modules/code-to-disk/test.js (needs bare 1.32+)
const fs = require('bare-fs')
const os = require('bare-os')
const path = require('bare-path')
const b4a = require('b4a')
const Corestore = require('corestore')
const RAM = require('random-access-memory')
const { create_autodisk } = require('autodisk')
const disk_loader = require('disk-loader')
const code_to_disk = require('./')

let failed = 0
main().then(done)

async function main () {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'code-to-disk-test-'))
  const app = path.join(root, 'project', 'app')
  // a small app: main.js requires a file next to it, a json file, a package from node_modules, b4a from builtins
  // and one file only inside a function that runs later. computed.js is only required by a computed name, unused.js by nothing
  write(path.join(root, 'project', 'package.json'), '{ "name": "project" }')
  write(path.join(app, 'main.js'), [
    "const hi = require('./lib/hi.js')",
    "const { name } = require('./config.json')",
    "const shout = require('shout')",
    "const b4a = require('b4a')",
    "const computed = './lib/computed.js'",
    "function later () { return require('./lib/later.js') }",
    'function never () { return require(computed) }',
    "module.exports = shout(hi + ' ' + name) + ' ' + later() + ' ' + b4a.toString(b4a.from('ok'))"
  ].join('\n'))
  write(path.join(app, 'lib', 'hi.js'), "module.exports = 'hi'")
  write(path.join(app, 'lib', 'later.js'), "module.exports = 'later'")
  write(path.join(app, 'lib', 'computed.js'), "module.exports = 'computed'")
  write(path.join(app, 'lib', 'unused.js'), "module.exports = 'unused'")
  write(path.join(app, 'config.json'), '{ "name": "lupay" }')
  write(path.join(app, 'node_modules', 'shout', 'package.json'), '{ "name": "shout", "main": "lib/index.js" }')
  write(path.join(app, 'node_modules', 'shout', 'lib', 'index.js'), "module.exports = text => text.toUpperCase() + '!'")
  const drive = create_autodisk({ store: new Corestore(RAM).namespace('app') })
  await drive.ready()
  const file = await code_to_disk({ drive, file: path.join(app, 'main.js'), builtins: { b4a } })
  check('gives back where the entry file is in the disk', file === '/main.js')
  const files = await list_files(drive)
  check('copies exactly the files the app requires, paths stay the same next to the entry file', files.join(' ') === '/config.json /lib/hi.js /lib/later.js /main.js /node_modules/shout/lib/index.js /node_modules/shout/package.json', files.join(' '))
  check('a file required only inside a function that runs later is copied too', files.includes('/lib/later.js'))
  check('a file required by a computed name is not copied', !files.includes('/lib/computed.js'))
  check('modules from builtins are not copied', !files.some(name => name.includes('b4a')))
  check('the package.json above the entry folder is not copied', !files.includes('/package.json'))
  check('the app runs from the disk', await disk_loader({ drive, file, builtins: { b4a } }) === 'HI LUPAY! later ok')
  const length = drive.base.view.drive.core.length
  await code_to_disk({ drive, file: path.join(app, 'main.js'), builtins: { b4a } })
  check('running it again copies nothing if no file changed', drive.base.view.drive.core.length === length)
  write(path.join(app, 'lib', 'hi.js'), "module.exports = 'hey'")
  await code_to_disk({ drive, file: path.join(app, 'main.js'), builtins: { b4a } })
  check('a changed file is copied again, only that one', drive.base.view.drive.core.length === length + 1)
  check('the app runs the changed code', await disk_loader({ drive, file, builtins: { b4a } }) === 'HEY LUPAY! later ok')
  write(path.join(app, 'package.json'), '{ "name": "app" }')
  await code_to_disk({ drive, file: path.join(app, 'main.js'), builtins: { b4a } })
  check('a package.json in the entry folder is copied', (await list_files(drive)).includes('/package.json'))
  // the loader skips a missing module while linking, so the copy works and the app only fails when it runs (see disk-loader tests)
  write(path.join(app, 'missing.js'), "module.exports = require('./nope.js')")
  check('a missing module does not stop the copy', await code_to_disk({ drive, file: path.join(app, 'missing.js') }) === '/missing.js')
  await drive.close()
  fs.rmSync(root, { recursive: true, force: true })
}

/***************************************
HELPERS
***************************************/
function check (name, ok, note = '') {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}${!ok && note ? `  (${note})` : ''}`)
  if (!ok) failed++
}

function done () {
  console.log(failed ? `${failed} failed` : 'all good')
  if (failed) throw new Error('code-to-disk tests failed')
}

function write (file, text) {
  fs.mkdirSync(path.dirname(file), { recursive: true })
  fs.writeFileSync(file, text)
}

async function list_files (drive) {
  const files = []
  for await (const entry of drive.base.view.drive.list('/')) files.push(entry.key)
  return files
}
